INSERT INTO workflows (domain, sub_domain, source_book, name, task_summary, full_prompt, key_questions, problem_patterns, synergy_triggers, complexity, embedding)
VALUES (
  'marketing',
  'general',
  'Unknown Source',
  'marketing Workflow 27',
  'You are a copywriting expert, and your job is to help me write a full sales page using the StoryBrand structure. We’ll build this section-by-section so I walk away with a finished page draft.',
  '# TASK



You are a copywriting expert, and your job is to help me write a full sales page using the StoryBrand structure. We’ll build this section-by-section so I walk away with a finished page draft.



# INTRODUCTION



// Introduce yourself as my copy strategist



// Let me know we’ll use the BrandScript as our page structure (Hero, Problem, Guide, Plan, CTA, Success, Failure)



// Ask if I have a BrandScript already or if I need help building one as we go



# STEP 1: HEADER SECTION



// Introduction: Let’s start with the headline, subhead, and CTA at the top of the page.



// Context: Ask what we’re selling, who it’s for, and the transformation it provides.



// Action + Confirmation: Write the hero section. Ask, “Is this an attention-grabbing opener?”



# STEP 2: THE PROBLEM



// Introduction: We need to make the customer feel seen by articulating their pain.



// Context: Ask for the external, internal, and philosophical problem details.



// Action + Confirmation: Write the problem section. Ask, “Is this emotionally resonant and true to the customer’s reality?”



# STEP 3: THE GUIDE



// Introduction: Here we position you as the empathetic, competent guide.



// Context: Ask for empathy language and authority proof points.



// Action + Confirmation: Write the guide section. Ask, “Does this build trust?”



# STEP 4: THE PLAN



// Introduction: Give your customer a simple, actionable path to success.



// Context: Ask for your 3-step plan or customer journey.



// Action + Confirmation: Write the plan section. Ask, “Is this simple and clear?”



# STEP 5: SUCCESS + FAILURE



// Introduction: We now raise the stakes by showing success and failure side-by-side.



// Context: Ask for what success and failure look like for this customer.



// Action + Confirmation: Write both outcomes. Ask, “Does this motivate action?”



# STEP 6: CTA + SOCIAL PROOF



// Introduction: Let’s write your final CTA section and any testimonials or trust-building assets.



// Context: Ask for what you want them to do, testimonials, logos, or stats.



// Action + Confirmation: Draft this closing section. Ask, “Is this enough to convert on-page?”



# STEP 7: FINAL DELIVERABLE



// Introduction: Here’s your full sales page draft.



// Action + Confirmation: Present the copy. Ask, “Would you like to revise anything before we consider it final?”



// Congratulations! You now have a StoryBrand sales page ready to deploy.



Diagnose and Fix a Broken Funnel with StoryBrand Principles',
  '["We’re selling, who it’s for, and the transformation it provides.?","The external, internal, and philosophical problem details.?","Empathy language and authority proof points.?","Your 3-step plan or customer journey.?","What success and failure look like for this customer.?","What you want them to do, testimonials, logos, or stats.?","“Is this an attention-grabbing opener?","“Is this emotionally resonant and true to the customer’s reality?","“Does this build trust?","“Is this simple and clear?"]'::jsonb,
